  'triage-processor': 'haiku', 'publisher': 'haiku', 'build-error-resolver': 'sonnet',
  'bookkeeper': 'haiku', 'quartermaster': 'haiku', 'observer': 'haiku',
  'doc-updater': 'haiku', 'docs-lookup': 'haiku', 'graph-analyst': 'haiku',
  'harness-cleaner': 'haiku',
};

// --- Complexity signals for model tier adjustment ---
// Downgrade model when task is simple; upgrade is never automatic (stay at default max)
const SIMPLE_TASK_SIGNALS = [
  'update', 'record', 'add frontmatter', 'mark', 'rename', 'move', 'fix frontmatter',
  'tag', 'index', 'list', 'count', 'check', 'validate', 'install',
];
const COMPLEX_TASK_SIGNALS = [
  'survey', 'analyze', 'architect', 'design', 'synthesize', 'critique',
  'evaluate trade', 'compare', 'novel', 'creative',
];

function selectModelTier(office, task) {
  const defaultModel = OFFICE_MODELS[office] || 'sonnet';
  const titleLower = (task.title || '').toLowerCase();

  // F3 offices always use haiku (or will become kernel tools — no LLM at all)
  const f3Offices = ['bookkeeper', 'docs-lookup', 'graph-analyst', 'harness-cleaner',
    'doc-updater', 'observer', 'quartermaster'];
  if (f3Offices.includes(office)) return 'haiku';

  // Simple tasks can downgrade: opus→sonnet, sonnet→haiku
  if (SIMPLE_TASK_SIGNALS.some(s => titleLower.includes(s))) {
    if (defaultModel === 'opus') return 'sonnet';
    if (defaultModel === 'sonnet') return 'haiku';
    return defaultModel;
  }

  // Complex tasks stay at default (never upgrade beyond office default)
  return defaultModel;
}

